import fs from 'node:fs/promises';const d='data/research/short-squeeze-sl-entry-20261107',x=JSON.parse(await fs.readFile(d+'/results.json')),fmt=(n,k=2)=>Number.isFinite(n)?n.toFixed(k):'—',pct=n=>fmt(n)+'%',label=g=>'SL'+g.config.slRoe+' / '+(g.config.beTriggerRoe===null?'không dời':'dời entry khi +'+g.config.beTriggerRoe+'% ROE');
let md='# SHORT ép LONG, lực bán ≥70%: giảm SL và dời về entry\n\nVersion '+x.protocol.version+'. Cùng30cảnh báo/29coin đã chọn trước đó, giữ nguyên entryAt và đường8h. Đã tải14.400nến1phút để so20cấu hình. Không thay bot hoặc lệnh Binance thật.\n\n';
md+='## Nhận xét chính\n\nTrong mẫu này, giảm SL hoặc dời về entry chưa cải thiện lợi nhuận trung bình. SL20%/15% đều ROE TB+2,27%, win73,33%; không có lệnh chạm hai mứcSL này trong8h. SL10% còn+2,03%,SL7,5%+2,12%,SL5%+1,99%. GiảmSL làm một số lệnh thoát trong nhịp hồi bất lợi, trong khi giữ tới8h có mức lỗ nhỏ hơn. Không có nghĩa SL rộng hơn an toàn: mẫu30lệnh này chưa chứa cúsqueeze chạmSL15/20 nên chưa đo được lợi ích chặn các khoản lỗ lớn.\n\nDời SL ngay khi giá chạm mốc lãi grossROE+3% làm ROE TB còn+1,69%; chạm+5%/+7% còn+2,02%. Nếu đợi nến1phút đóng đủ điều kiện rồi áp dụng từ phút kế tiếp (bản chính), kết quả lần lượt+1,94%/+2,02%/+2,27%. Dời quá sớm cắt một số lệnh sau đó tiếp tục đi xuống. Các cấu hình được so hồi cứu trên mẫu cũ, không phải xác nhận ngưỡng tối ưu.\n\nEntry là hòa giá trước phí. Ở3×, chi phí0,14%notional tương ứng−0,42%ROE chưa kểfunding. Một lệnh đóng tại entry có thể vẫn lỗnet.\n\n';
md+='## Giảm SL, chưa dời entry\n\nGiữ TP10%grossROE, max8h, leverage3×. SL là phần trămROE ký quỹ, không phải phần trăm biến độnggiá.\n\n| SL grossROE | Khoảng giá bất lợi ở3× | Win net | ROE TB | ROE stress | Chạm SL ban đầu | Lệnh lỗ nhất quan sát |\n|---|---:|---:|---:|---:|---:|---:|\n'+x.protocol.stopRoes.map(sl=>{const s=x.groups['SL'+sl+'_BENONE'].closed;return'| '+sl+'% | '+pct(sl/3)+' | '+pct(s.winPct)+' | '+pct(s.meanRoe)+' | '+pct(s.stressMeanRoe)+' | '+s.initialSL+'/30 | '+pct(s.worstRoe)+' |';}).join('\n')+'\n\nSL20/15 chỉ có1lệnh TP và29lệnh đóng sau8h; vì vậy kết quả phụ thuộc giới hạn giữ8h. SL10/7,5 chạm1lệnh USTCUSDT; SL5 chạm thêmLQTY/COOKIE. WorstROE quan sát không phải mức lỗ tối đa có thể xảy ra; gap/trượt có thể vượtSL.\n\n';
md+='## Dời SL về entry với SL ban đầu20%\n\nMốc lãi là grossROE ở3×: +3/+5/+7% tương ứng giá giảm1/1,67/2,33%. Mức entry là giá vào ban đầu, không cộng bù phí.\n\n| Mốc lãi | Đóng1m mới dời: ROE TB | Win net | Số lần thoát tại entry | Chạm mốc là dời: ROE TB |\n|---|---:|---:|---:|---:|\n'+[3,5,7].map(be=>{const g=x.groups['SL20_BE'+be];return'| +'+be+'% | '+pct(g.closed.meanRoe)+' | '+pct(g.closed.winPct)+' | '+g.closed.entrySL+'/30 | '+pct(g.touchWorst.meanRoe)+(Math.abs(g.touchWorst.meanRoe-g.touchBest.meanRoe)>1e-8?' → '+pct(g.touchBest.meanRoe):'')+' |';}).join('\n')+'\n\nBản đóng1m: chỉ dời sau khi CLOSE đạt mốc; stop mới có hiệu lực từ phút kế tiếp. Bản chạm mốc: xét các thứ tự giá đi qua OHLC1m, gồm đường chạmtrigger rồi hồi lênhigh trước khi xuốnglow; giữ cả nhánh đã thoát và còn sống để không mặc định có lợi. Trong bộ30case này các thứ tự được kiểm không làm khác netROE cuối của mỗi cấu hình chạm mốc; vẫn chưa có dữ liệu tick để xác nhận từng giây.\n\nSL15 kết hợp dời entry có cùng kết quảSL20 tương ứng trong mẫu này vì chưa có nhịp chạmSL15.\n\n';
md+='## Tất cả20cấu hình — bản đóng1phút\n\n| Cấu hình | Win net | ROE TB | SL đầu / SL entry | Lệnh gốc thắng bị cắt thành không thắng | ThoátSL rồi quay xuống dưới entry | SL rồi chạmTP gốc ở phút sau |\n|---|---:|---:|---:|---:|---:|---:|\n'+Object.values(x.groups).map(g=>{const s=g.closed;return'| '+label(g)+' | '+pct(s.winPct)+' | '+pct(s.meanRoe)+' | '+s.initialSL+' / '+s.entrySL+' | '+g.baselineWinnersCut+' | '+s.stopThenBelowEntry+' | '+s.stopThenTarget+' |';}).join('\n')+'\n\nCác mốc sau thoát chỉ tính nến có openTime lớn hơn exitAt, không tính cùng phút chưa biết thứ tự. Quay lại dướientry không đồng nghĩa có lãi net sau phí. Không case nào chạmTP10%grossROE sauSL ở phút sau trong cửa sổ8h, nhưng có case hồi xuống dướientry hoặc cólãi nhẹ sau đó.\n\n';
md+='## Ví dụ cụ thể\n\n1000RATSUSDT: cấu hình gốc đóng8h netROE+6,92%. Dời SL ở+5% khiến thoát vềentry netROE−0,36% sau phí/funding; giá sau đó vẫn xuống. Đây là lý do ROE trung bình bị giảm, dù stop theo giá được gọi là hòa vốn.\n\nUSTCUSDT: gốc không chạmSL20 và đóng8h−3,46%netROE. SL10 thoát sớm−10,40%,SL7,5−7,90%,SL5−5,40%. Chặn lỗ ở một nhịp tăng giữa đường có thể tạo kết quả lỗ hơn việc đóng cuối kỳ trong ví dụ này; không suy rằng bỏSL là an toàn.\n\nCOOKIEUSDT:SL5 thoát khoảng−5,41%, sau đó có quay xuống dướientry nhưng chưa chạmTP10 trong8h; gốc cuối kỳ−2,98%.\n\n';
md+='## Độ chắc chắn và đối chiếu thời gian\n\n| Cấu hình | Phần trước: n / ROE TB | Phần cuối: n / ROE TB | CI95% Δ ROE so gốc theo coin (điểm%) |\n|---|---:|---:|---:|\n'+['SL15_BENONE','SL10_BENONE','SL7.5_BENONE','SL5_BENONE','SL20_BE3','SL20_BE5','SL20_BE7'].map(id=>{const g=x.groups[id];return'| '+label(g)+' | '+g.earlier.n+' / '+pct(g.earlier.meanRoe)+' | '+g.later.n+' / '+pct(g.later.meanRoe)+' | '+g.ciCoin.deltaMeanRoe95.map(a=>fmt(a)).join(' → ')+' |';}).join('\n')+'\n\nBootstrap2.000lần theo coin vàkhối2h, cùng event ghép cặp; chưa chỉnh thử20cấu hình. Đây là tối ưu tham số hồi cứu trên nhóm70% đã được chọn sau nghiên cứu trước, chỉ30mẫu/29coin. Phần trước20/phầnsau10 chỉmô tả; nguồn không có train/test độc lập saupurge8h. CI[0;0] khi cấu hình không thay kết quả có nghĩa chưa có giao dịch bịtácđộng, không chứng minh rủi ro bằng nhau ởtươnglai.\n\n';
md+='## Nguồn và xác minh\n\nCùng frozen eventID, cùng entryAt trì hoãn sau Discord, cùng max8h vàfunding của nghiên cứu trước. Chỉ bổ sung nếnPRICE1m Binance cho đúng30đườnggiá; không tải lại cávoi/Crowd hoặc đổi tínhiệu. Stop/TP dùng PRICE trong môphỏng này để so cùng nguồn cũ; chưa môphỏng triggerMARK thực tế, ticksize, độtrễhủythaystop, sổlệnh,khớplệnh hoặc vốn/cap. Chi phí hai chiều0,14%notional gồm phí/trượt giả định, stress0,30%; không giả định khớpentry miễnphí.\n\nBaselineSL20/NONE trên1m tái tạo chính xác netROE và giá vào/ra của30case5m gốc. Có84sai khác nếu cộngOHLC1m một cách máy móc, đều ở bucket có phútđầu khônggiao dịch (carrygiá cũ); khi tổng hợp các phút cógiao dịch, toàn bộ11.520trườnggiá5m khớp. Không có lệchOHLCgiao dịch còn lại bị che giấu.\n\nĐã kiểmtraSHA25630filenến và2nguồncohort/funding; replay độc lập600case bằng đơn vịROE chuẩn hóa, đối chiếu entry/exit/time/kind/arming/PnL và20group. Unitcase kiểmphíBE,nextminuteactivation,samebarSL-first,trigger→hồi→TP,gapbấtlợi,khôngarmtươnglai,SLnhỏ vàchiềufundingSHORT. Model1/3 khôngđượctínhlại vìSLkhôngthayđườnggiá; quét11/28tậpnguồngiữnguyênvàkhôngđồngnghĩavẫncònlệnhđểhưởngnhịpđó.\n\nKhông thay Binance/entry/size/leverage/SL/TP/gate/Discord/WHITELIST/WebPushOFF hoặc JSONruntime/history/cooldown. Chỉ thêm nghiên cứu versioned,tài liệu vàfolder báo cáo; khôngrestart,khôngđặtlệnh hoặcgửitinDiscord.\n';
await fs.writeFile(d+'/BAO_CAO.md',md);console.log('REPORT_WRITTEN');

